"""Read-only, paginated history over native workbench sessions and attempts."""

import os
import re
import sys
import unicodedata
from datetime import datetime, timezone

from fastapi import Depends, FastAPI, HTTPException, Query, Request
from src.api.mona_workbench import workbench_context
from src.api.security import require_auth

_SYMBOL = re.compile(r"^[0-9]{6}\.(?:SH|SZ|BJ)$")
_TASKS = {"comprehensive", "fundamental", "technical", "risk"}
_ACTIVE = {"pending", "running", "waiting_user", "idle"}
_UNFINISHED = {"failed", "cancelled", "interrupted"}
_QUERY_FIELDS = {"symbol", "q", "task", "state", "offset", "limit"}


def _utc_epoch(value: str) -> float:
    parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc).timestamp()


def _rows(store, symbol: str) -> list[dict]:
    sessions = {}
    contexts = {}
    for session in store.list_sessions(limit=sys.maxsize):
        context = workbench_context(session.config)
        if context is not None and context["symbol"] == symbol:
            sessions[session.session_id] = session
            contexts[session.session_id] = context

    by_session = {}
    for attempt in store.list_attempts():
        if attempt.session_id in sessions:
            by_session.setdefault(attempt.session_id, []).append(attempt)

    rows = []
    for session_id, session in sessions.items():
        context = contexts[session_id]
        title = session.title if isinstance(session.title, str) else ""
        attempts = by_session.get(session_id, [])
        if not attempts:
            rows.append({
                "session_id": session_id,
                "attempt_id": None,
                "title": title,
                "task": context["task"],
                "mode": context["mode"],
                "status": "idle",
                "created_at": session.created_at,
                "completed_at": None,
            })
            continue
        for attempt in attempts:
            rows.append({
                "session_id": session_id,
                "attempt_id": attempt.attempt_id,
                "title": title,
                "task": context["task"],
                "mode": context["mode"],
                "status": getattr(attempt.status, "value", attempt.status),
                "created_at": attempt.created_at,
                "completed_at": attempt.completed_at,
            })
    return rows


def _matches_state(status: str, state: str) -> bool:
    if state == "all":
        return True
    if state == "completed":
        return status == "completed"
    if state == "active":
        return status in _ACTIVE
    return status in _UNFINISHED


def register_mona_workbench_history(app: FastAPI) -> None:
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    @app.get("/mona/workbench-history", dependencies=[Depends(require_auth)])
    def get_workbench_history(
        request: Request,
        symbol: str,
        q: str = "",
        task: str = "all",
        state: str = "all",
        offset: int = Query(0, ge=0, le=1_000_000),
        limit: int = Query(10, ge=1, le=50),
    ) -> dict:
        query = request.query_params
        if (not set(query).issubset(_QUERY_FIELDS)
            or "symbol" not in query
            or any(len(query.getlist(key)) != 1 for key in query)):
            raise HTTPException(status_code=422, detail="Invalid workbench history query")
        if not _SYMBOL.fullmatch(symbol):
            raise HTTPException(status_code=422, detail="Invalid stock symbol")
        clean_q = q.strip()
        if len(clean_q) > 120 or any(unicodedata.category(char) == "Cc" for char in q):
            raise HTTPException(status_code=422, detail="Invalid title search")
        if task != "all" and task not in _TASKS:
            raise HTTPException(status_code=422, detail="Invalid workbench task")
        if state not in {"all", "completed", "active", "unfinished"}:
            raise HTTPException(status_code=422, detail="Invalid workbench state")

        host = sys.modules.get("api_server") or sys.modules.get("agent.api_server")
        service = host._get_session_service() if host is not None else None
        if service is None:
            raise HTTPException(status_code=503, detail="Session runtime unavailable")

        title_query = clean_q.casefold()
        rows = [row for row in _rows(service.store, symbol)
                if (task == "all" or row["task"] == task)
                and _matches_state(row["status"], state)
                and (not title_query or title_query in row["title"].casefold())]
        rows.sort(key=lambda row: (-_utc_epoch(row["created_at"]), row["session_id"], row["attempt_id"] or ""))
        return {"symbol": symbol, "offset": offset, "limit": limit, "total": len(rows),
                "items": rows[offset:offset + limit]}
